952:         if request.schema_version != RUNTIME_SCHEMA_VERSION {
953:             return Err(RuntimeError::invalid(
954:                 "unsupported runtime schema version",
955:                 "schemaVersion",
956:             ));
957:         }
958:         if request.limit == 0 || request.limit > super::MAX_RUNTIME_LIST_LIMIT {
959:             return Err(RuntimeError::invalid(
960:                 format!("limit must be in 1..={}", super::MAX_RUNTIME_LIST_LIMIT),
961:                 "limit",
962:             ));
963:         }
964:         if let Some(cursor) = &request.cursor {
965:             crate::universal::validate_id(&cursor.workspace_id, "cursor.workspaceId")
966:                 .map_err(map_universal_error)?;
967:         }
968:         let inventory =
969:             list_open_workspace_record_inventory(&self.executor).map_err(map_universal_error)?;
970:         let (records, next_cursor) =
971:             workspace_record_page(inventory.records, request.limit, request.cursor.as_ref());
972:         let mut workspaces = Vec::with_capacity(records.len());
973:         let mut issues = inventory
974:             .issues
975:             .into_iter()
976:             .map(|issue| {
977:                 workspace_issue(
978:                     &issue.workspace_id,
979:                     RuntimeWorkspaceIssueStage::Inventory,
980:                     map_universal_error(issue.error),
981:                 )
982:             })
983:             .collect::<Vec<_>>();
984:         for record in records {
985:             let active_job_ids = match self
986:                 .registry
987:                 .active_job_ids_for_workspace(&record.workspace_id)
988:             {
989:                 Ok(active_job_ids) => active_job_ids,
990:                 Err(error) if error.is_reconciliation_fatal() => return Err(error),
991:                 Err(error) => {
992:                     issues.push(workspace_issue(
993:                         &record.workspace_id,
994:                         RuntimeWorkspaceIssueStage::ActiveJobs,
995:                         error,
996:                     ));
997:                     continue;
998:                 }
999:             };
1000:             let (current_head_revision, dirty) =
1001:                 match workspace_head_and_dirty_at(Path::new(&record.workspace_path)) {
1002:                     Ok(projection) => projection,
1003:                     Err(error) => {
1004:                         let stage = if error.code
1005:                             == crate::universal::UniversalExecErrorCode::RevisionNotFound
1006:                         {
1007:                             RuntimeWorkspaceIssueStage::HeadRevision
1008:                         } else {
1009:                             RuntimeWorkspaceIssueStage::DirtyProbe
1010:                         };
1011:                         issues.push(workspace_issue(
1012:                             &record.workspace_id,
1013:                             stage,
1014:                             map_universal_error(error),
1015:                         ));
1016:                         continue;
1017:                     }
1018:                 };
1019:             let source_state_digest = if request.include_source_state_digest {
1020:                 match workspace_source_state_digest(&self.executor, &record.workspace_id) {
1021:                     Ok(digest) => Some(digest),
1022:                     Err(error) => {
1023:                         issues.push(workspace_issue(
1024:                             &record.workspace_id,
1025:                             RuntimeWorkspaceIssueStage::SourceStateDigest,
1026:                             map_universal_error(error),
1027:                         ));
1028:                         continue;
1029:                     }
1030:                 }
1031:             } else {
1032:                 None
1033:             };
1034:             workspaces.push(Self::workspace_summary_from_parts(
1035:                 &record,
1036:                 current_head_revision,
1037:                 dirty,
1038:                 source_state_digest,
1039:                 active_job_ids,
1040:             ));
1041:         }
1042:         Ok(RuntimeWorkspaceListResult {
1043:             workspaces,
1044:             next_cursor,
1045:             issues,
1046:         })
1047:     }
