1911:         }
1912:         if let Err(error) = self.verify_committed_host_dependencies(&attempt.job_id) {
1913:             if matches!(
1914:                 error.code,
1915:                 RuntimeErrorCode::WorkspaceStateMismatch | RuntimeErrorCode::InvalidRequest
1916:             ) {
